<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --surface: #ffffff;
      --surface-soft: #f8fafc;
      --text: #182230;
      --muted: #526071;
      --accent: #6d28d9;
      --accent-dark: #4c1d95;
      --border: #dbe3ef;
      --shadow: 0 24px 60px rgba(24, 34, 48, 0.12);
      --radius: 1.25rem;
    }

    * {
      box-sizing: border-box;
    }

    html {
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      line-height: 1.5;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(109, 40, 217, 0.16), transparent 36rem),
        linear-gradient(135deg, #f8fbff 0%, var(--bg) 58%, #eef2ff 100%);
    }

    body {
      min-height: 100vh;
      margin: 0;
    }

    .skip-link {
      position: absolute;
      left: 1rem;
      top: 1rem;
      z-index: 1;
      transform: translateY(-150%);
      border-radius: 999px;
      padding: 0.75rem 1rem;
      color: #ffffff;
      background: var(--accent-dark);
      font-weight: 700;
      text-decoration: none;
    }

    .skip-link:focus {
      transform: translateY(0);
      outline: 3px solid #facc15;
      outline-offset: 3px;
    }

    main {
      width: min(100% - 2rem, 980px);
      margin: 0 auto;
      padding: 4rem 0;
    }

    .hero {
      display: grid;
      gap: 1rem;
      margin-bottom: 2rem;
      text-align: center;
    }

    .eyebrow {
      justify-self: center;
      margin: 0;
      border: 1px solid rgba(109, 40, 217, 0.22);
      border-radius: 999px;
      padding: 0.35rem 0.8rem;
      color: var(--accent-dark);
      background: rgba(109, 40, 217, 0.08);
      font-size: 0.875rem;
      font-weight: 800;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.25rem, 8vw, 4.75rem);
      line-height: 0.95;
      letter-spacing: -0.06em;
    }

    .intro {
      max-width: 44rem;
      margin: 0 auto;
      color: var(--muted);
      font-size: clamp(1rem, 2vw, 1.2rem);
    }

    .faq-card {
      border: 1px solid rgba(219, 227, 239, 0.9);
      border-radius: calc(var(--radius) + 0.5rem);
      padding: clamp(0.75rem, 2vw, 1.25rem);
      background: rgba(255, 255, 255, 0.82);
      box-shadow: var(--shadow);
      backdrop-filter: blur(18px);
    }

    .example {
      border: 1px solid var(--border);
      border-radius: var(--radius);
      background: var(--surface);
      overflow: clip;
    }

    .example + .example {
      margin-top: 0.875rem;
    }

    .question {
      margin: 0;
    }

    .question button {
      display: grid;
      grid-template-columns: 1fr auto;
      gap: 1rem;
      align-items: center;
      width: 100%;
      border: 0;
      padding: clamp(1rem, 3vw, 1.35rem);
      color: var(--text);
      background: transparent;
      font: inherit;
      font-size: clamp(1rem, 2vw, 1.15rem);
      font-weight: 800;
      text-align: left;
      cursor: pointer;
    }

    .question button:hover {
      background: var(--surface-soft);
    }

    .question button:focus-visible {
      position: relative;
      z-index: 1;
      outline: 3px solid var(--accent);
      outline-offset: -3px;
    }

    .question button::after {
      width: 2rem;
      height: 2rem;
      border: 1px solid rgba(109, 40, 217, 0.28);
      border-radius: 999px;
      color: var(--accent-dark);
      background: rgba(109, 40, 217, 0.08);
      content: "+";
      display: grid;
      place-items: center;
      font-size: 1.35rem;
      font-weight: 700;
      line-height: 1;
      transition: transform 160ms ease, background-color 160ms ease;
    }

    .question button[aria-expanded="true"]::after {
      content: "−";
      transform: rotate(180deg);
      background: rgba(109, 40, 217, 0.14);
    }

    .details {
      border-top: 1px solid var(--border);
      padding: 0 clamp(1rem, 3vw, 1.35rem) clamp(1rem, 3vw, 1.35rem);
      color: var(--muted);
      background: linear-gradient(180deg, rgba(248, 250, 252, 0.7), #ffffff);
    }

    .details p {
      max-width: 62ch;
      margin: 1rem 0 0;
    }

    @media (prefers-reduced-motion: reduce) {
      *,
      *::before,
      *::after {
