        transition-duration: 0.01ms !important;
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
      }
    }

    @media (forced-colors: active) {
      .faq-card,
      .example,
      .eyebrow,
      .question button::after {
        border: 1px solid CanvasText;
        box-shadow: none;
      }

      .question button:focus-visible {
        outline: 3px solid Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <header class="hero">
      <p class="eyebrow">Cat care basics</p>
      <h1>Frequently asked questions about cats</h1>
      <p class="intro">Quick answers for curious cat people, from purring and play to naps, whiskers, and healthy routines.</p>
    </header>

    <section class="faq-card" aria-label="Cat questions and answers">
      <div class="example">
        <h2 class="question">
          <button type="button" id="question-purr" aria-expanded="true" aria-controls="answer-purr">
            Why do cats purr?
          </button>
        </h2>
        <div class="details" id="answer-purr" aria-labelledby="question-purr">
          <p>Cats often purr when they feel relaxed, but purring can also be self-soothing when they are stressed, injured, or seeking comfort.</p>
        </div>
      </div>

      <div class="example">
        <h2 class="question">
          <button type="button" id="question-sleep" aria-expanded="true" aria-controls="answer-sleep">
            How much do cats sleep?
          </button>
        </h2>
        <div class="details" id="answer-sleep" aria-labelledby="question-sleep">
          <p>Most adult cats sleep 12 to 16 hours a day. Kittens and senior cats may sleep even more as their bodies grow, recover, or conserve energy.</p>
        </div>
      </div>

      <div class="example">
        <h2 class="question">
          <button type="button" id="question-knead" aria-expanded="true" aria-controls="answer-knead">
            Why do cats knead blankets or laps?
          </button>
        </h2>
        <div class="details" id="answer-knead" aria-labelledby="question-knead">
          <p>Kneading is a comforting behavior that begins in kittenhood. Adult cats may knead when they are content, marking a familiar spot, or getting cozy.</p>
        </div>
      </div>

      <div class="example">
        <h2 class="question">
          <button type="button" id="question-whiskers" aria-expanded="true" aria-controls="answer-whiskers">
            What are cat whiskers for?
          </button>
        </h2>
        <div class="details" id="answer-whiskers" aria-labelledby="question-whiskers">
          <p>Whiskers are sensitive touch sensors. They help cats judge spaces, notice air movement, and understand nearby objects, especially in low light.</p>
        </div>
      </div>

      <div class="example">
        <h2 class="question">
          <button type="button" id="question-play" aria-expanded="true" aria-controls="answer-play">
            How often should I play with my cat?
          </button>
        </h2>
        <div class="details" id="answer-play" aria-labelledby="question-play">
          <p>Short daily play sessions are ideal. Two or three sessions of 10 to 15 minutes can help cats exercise, practice hunting behaviors, and stay mentally engaged.</p>
        </div>
      </div>
    </section>
  </main>

  <script>
    document.querySelectorAll('.example').forEach((item) => {
      const button = item.querySelector('button[aria-expanded]');
      const panel = item.querySelector('.details');

      button.setAttribute('aria-expanded', 'false');
      panel.hidden = true;

      button.addEventListener('click', () => {
        const isOpen = button.getAttribute('aria-expanded') === 'true';
        button.setAttribute('aria-expanded', String(!isOpen));
        panel.hidden = isOpen;
      });

      button.addEventListener('keydown', (event) => {
        if (event.key === 'Escape' && button.getAttribute('aria-expanded') === 'true') {
          button.setAttribute('aria-expanded', 'false');
          panel.hidden = true;
        }
      });
    });
  </script>
</body>
</html>
